SELECT i.id, i.booking_date, i.value_date, i.amount, i.currency, i.direction, i.booking_text, i.remittance_info, i.counterparty_name, i.counterparty_iban, i.creditor_id, i.content_hash, i.occurrence_index FROM ( SELECT t.*, CASE WHEN t.attributed_name IS NOT NULL THEN 'name' WHEN t.creditor_id IS NOT NULL THEN 'creditor_id' WHEN t.counterparty_iban IS NOT NULL THEN 'iban' WHEN t.counterparty_name IS NOT NULL THEN 'name' END AS identity_type, CASE WHEN t.attributed_name IS NOT NULL THEN upper(trim(regexp_replace(normalize(t.attributed_name, NFC), '\s+', ' ', 'g'))) WHEN t.creditor_id IS NOT NULL THEN t.creditor_id WHEN t.counterparty_iban IS NOT NULL THEN t.counterparty_iban WHEN t.counterparty_name IS NOT NULL THEN upper(trim(regexp_replace(normalize(t.counterparty_name, NFC), '\s+', ' ', 'g'))) END AS identity_value FROM transactions t WHERE NOT EXISTS (SELECT 1 FROM transactions c WHERE c.split_parent_content_hash = t.content_hash AND c.split_parent_occurrence_index = t.occurrence_index) ) i LEFT JOIN counterparty_alias al ON al.identity_type = i.identity_type AND al.identity_value = i.identity_value LEFT JOIN counterparties own ON own.identity_type = i.identity_type AND own.identity_value = i.identity_value WHERE COALESCE(al.canonical_counterparty_id, own.id) = ? AND ( (CAST(? AS date) IS NOT NULL AND CAST(? AS date) IS NOT NULL AND i.booking_date BETWEEN CAST(? AS date) AND CAST(? AS date)) OR ((CAST(? AS date) IS NULL OR CAST(? AS date) IS NULL) AND (CAST(? AS integer) IS NULL OR i.booking_date >= CURRENT_DATE - (CAST(? AS integer) * INTERVAL '1 day'))) ) ORDER BY i.booking_date DESC
